import { createHash } from "node:crypto";
import { evaluateEvidenceVerifier } from "./evidence-verifier";

export type VerifierCompletionVerdict =
  | "approved"
  | "insufficient-evidence"
  | "rejected"
  | "out-of-scope";

export type VerifierCompletionStatus =
  | "pending"
  | "in-progress"
  | "blocked"
  | "done"
  | string;

export interface VerifierCompletionScope {
  readonly taskIds: readonly string[];
}

export interface VerifierCompletionTask {
  readonly taskId: string;
  readonly evidence: unknown;
  readonly priorStatus?: VerifierCompletionStatus | null;
}

export interface VerifierCompletionRequest {
  readonly scope: VerifierCompletionScope;
  readonly tasks: readonly VerifierCompletionTask[];
}

export interface VerifierCompletionStateTransition {
  readonly from: VerifierCompletionStatus;
  readonly to: VerifierCompletionStatus;
}

export interface VerifierCompletionVerdictRecord {
  readonly taskId: string;
  readonly verdict: VerifierCompletionVerdict;
  readonly evidenceDigest: string;
  readonly findingCodes: readonly string[];
  readonly priorStatus: VerifierCompletionStatus | null;
  readonly grantsPublish: false;
  readonly grantsProductLock: false;
}

export interface VerifierCompletionResult {
  readonly record: VerifierCompletionVerdictRecord;
  readonly transition: VerifierCompletionStateTransition | null;
}

export interface VerifierCompletionRevocation {
  readonly taskId: string;
  readonly from: "done";
  readonly to: VerifierCompletionStatus;
}

export type EvidenceVerifierEvaluator = (input: unknown) => unknown;

const DEFAULT_EVALUATOR = evaluateEvidenceVerifier as unknown as EvidenceVerifierEvaluator;

function canonicalize(value: unknown): string {
  if (value === null || typeof value !== "object") {
    return JSON.stringify(value);
  }
  if (Array.isArray(value)) {
    return `[${value.map(canonicalize).join(",")}]`;
  }
  const object = value as Record<string, unknown>;
  return `{${Object.keys(object)
    .sort()
    .map((key) => `${JSON.stringify(key)}:${canonicalize(object[key])}`)
    .join(",")}}`;
}

export function digestVerifierEvidence(evidence: unknown): string {
  return `sha256:${createHash("sha256").update(canonicalize(evidence)).digest("hex")}`;
}

function readResultValue(result: unknown, keys: readonly string[]): unknown {
  if (!result || typeof result !== "object") {
    return undefined;
  }
  const object = result as Record<string, unknown>;
  for (const key of keys) {
    if (object[key] !== undefined) {
      return object[key];
    }
  }
  return undefined;
}

function normalizeFindingCodes(value: unknown): readonly string[] {
  const candidate = Array.isArray(value)
    ? value
    : value && typeof value === "object"
      ? readResultValue(value, ["findingCodes", "findings", "codes"])
      : undefined;
  if (!Array.isArray(candidate)) {
    return [];
  }
  return [...new Set(candidate.filter((item): item is string => typeof item === "string"))].sort();
}

function normalizeVerdict(result: unknown): Exclude<VerifierCompletionVerdict, "out-of-scope"> {
  const value = readResultValue(result, ["status", "verdict", "outcome", "result"]);
  const normalized = typeof value === "string" ? value.toLowerCase().replace(/_/g, "-") : "";
  if (normalized === "completed" || normalized === "approved") {
    return "approved";
  }
  if (normalized === "insufficient-evidence" || normalized === "insufficient-evidence-required") {
    return "insufficient-evidence";
  }
  return "rejected";
}

export function evaluateVerifierCompletionVerdict(
  request: VerifierCompletionRequest,
  evaluator: EvidenceVerifierEvaluator = DEFAULT_EVALUATOR,
): readonly VerifierCompletionResult[] {
  const authorized = new Set(request.scope.taskIds);
  return request.tasks.map((task) => {
    const priorStatus = task.priorStatus ?? null;
    if (!authorized.has(task.taskId)) {
      return {
        record: {
          taskId: task.taskId,
          verdict: "out-of-scope",
          evidenceDigest: digestVerifierEvidence(task.evidence),
          findingCodes: [],
          priorStatus,
          grantsPublish: false,
          grantsProductLock: false,
        },
        transition: null,
      };
    }

    const evaluation = evaluator({
      taskId: task.taskId,
      evidence: task.evidence,
    });
    const verdict = normalizeVerdict(evaluation);
    const findingCodes = normalizeFindingCodes(evaluation);
    const record: VerifierCompletionVerdictRecord = {
      taskId: task.taskId,
      verdict,
      evidenceDigest: digestVerifierEvidence(task.evidence),
      findingCodes,
      priorStatus,
      grantsPublish: false,
      grantsProductLock: false,
    };
    return {
      record,
      transition:
        verdict === "approved" && priorStatus !== null
          ? { from: priorStatus, to: "done" }
          : null,
    };
  });
}

export function revokeVerifierCompletionVerdict(
  record: VerifierCompletionVerdictRecord,
): VerifierCompletionRevocation | null {
  if (record.verdict !== "approved" || record.priorStatus === null) {
    return null;
  }
  return {
    taskId: record.taskId,
    from: "done",
    to: record.priorStatus,
  };
}

